(() => {
  const header = document.querySelector('.totonoe-shared-header');
  if (!header) return;
  header.querySelectorAll('a').forEach(link => {
    const path = new URL(link.href, location.href).pathname;
    if (path === '/projects/totonoe/tsuzuri/') link.textContent = 'つづり｜TSUZURI';
    if (path === '/projects/totonoe/tsumami/') link.textContent = 'つまみ｜TSUMAMI';
  });
  const characterImages = {"tsugumo":"data:image/webp;base64,","hakuto":"data:image/webp;base64,","mion":"data:image/webp;base64,"};
  const makeCharacters = (names, className) => {
    const group = document.createElement('span'); group.className = className; group.setAttribute('aria-hidden', 'true');
    names.forEach(name => { const img = document.createElement('img'); img.src = characterImages[name]; img.alt = ''; img.width = 180; img.height = 180; img.decoding = 'async'; group.appendChild(img); });
    return group;
  };
  const brand = header.querySelector('.brand');
  brand.appendChild(makeCharacters(['tsugumo'], 'brand-character'));
  const themes = [
    {key:'seminar', names:['tsugumo'], note:'いっしょに学ぶ', welcome:'学びの時間へ、ようこそ。'},
    {key:'contents', names:['hakuto'], note:'ひとつずつ、知る', welcome:'気になることから、ひとつずつ。'},
    {key:'service', names:['mion'], note:'仕事の一歩へ', welcome:'あなたに合う学び方を見つけよう。'},
    {key:'team', names:['tsugumo','hakuto','mion'], note:'私たちの小さな物語', welcome:'3人と、整える世界へ。'}
  ];
  header.querySelectorAll('.nav-dropdown').forEach((item, i) => {
    const theme = themes[i]; if (!theme) return;
    item.dataset.character = theme.key;
    const link = item.querySelector('.nav-main');
    const label = document.createElement('span'); label.className = 'nav-label'; label.textContent = i === 3 ? 'チーム' : link.textContent;
    const note = document.createElement('small'); note.className = 'nav-note'; note.textContent = theme.note;
    link.replaceChildren(label, note);
    item.appendChild(makeCharacters(theme.names, 'nav-characters'));
    const menu = item.querySelector('.nav-menu');
    const welcome = document.createElement('div'); welcome.className = 'nav-welcome';
    welcome.appendChild(makeCharacters(theme.names, 'menu-characters'));
    const copy = document.createElement('p'); copy.textContent = theme.welcome; welcome.appendChild(copy); menu.prepend(welcome);
    menu.querySelectorAll('a').forEach((entry, number) => { const marker=document.createElement('span'); marker.className='nav-link-number'; marker.textContent=String(number+1).padStart(2,'0'); marker.setAttribute('aria-hidden','true'); entry.prepend(marker); });
    const button=item.querySelector('.header-menu-toggle');
    button.setAttribute('aria-label', (i === 3 ? 'チーム' : label.textContent) + 'の項目を開く');
    menu.id = 'header-menu-' + theme.key; button.setAttribute('aria-controls',menu.id);
  });

  const nav = header.querySelector('#siteNav'), toggle = header.querySelector('#navToggle');
  // Capture avoids duplicate toggles from existing page-specific navigation code.
  toggle.addEventListener('click', e => {
    e.stopImmediatePropagation();
    const open = nav.classList.toggle('open');
    toggle.setAttribute('aria-expanded', String(open));
    toggle.setAttribute('aria-label', open ? 'メニューを閉じる' : 'メニューを開く');
  }, true);
  header.querySelectorAll('.header-menu-toggle').forEach(button => button.addEventListener('click', e => {
    e.stopImmediatePropagation();
    const open = button.parentElement.classList.toggle('menu-open');
    button.parentElement.classList.remove('menu-dismissed');
    button.setAttribute('aria-expanded', String(open));
  }, true));
  header.querySelectorAll('.nav-dropdown').forEach(item => {
    const button = item.querySelector('.header-menu-toggle');
    item.addEventListener('mouseenter', () => { item.classList.remove('menu-dismissed'); if (window.matchMedia('(min-width:861px) and (hover:hover)').matches) button.setAttribute('aria-expanded','true'); });
    item.addEventListener('mouseleave', () => { item.classList.remove('menu-dismissed'); if (!item.contains(document.activeElement) && !item.classList.contains('menu-open')) button.setAttribute('aria-expanded','false'); });
    item.addEventListener('focusin', () => { item.classList.remove('menu-dismissed'); if (window.matchMedia('(min-width:861px)').matches) button.setAttribute('aria-expanded','true'); });
    item.addEventListener('focusout', e => { if (!item.contains(e.relatedTarget)) { item.classList.remove('menu-open'); button.setAttribute('aria-expanded','false'); } });
  });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') header.querySelectorAll('.nav-dropdown').forEach(item => item.classList.add('menu-dismissed')); });
  const close = () => { nav.classList.remove('open'); toggle.setAttribute('aria-expanded', 'false'); toggle.setAttribute('aria-label', 'メニューを開く'); };
  nav.addEventListener('click', e => { if (e.target.closest('a')) close(); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') { close(); header.querySelectorAll('.menu-open').forEach(el => el.classList.remove('menu-open')); header.querySelectorAll('.header-menu-toggle').forEach(el => el.setAttribute('aria-expanded', 'false')); } });
})();
